// Regex for validating filename characters. Allows alphanumeric, underscore, hyphen, and a single dot for extension.
// Refined regex to allow an optional extension with a single dot.
var validFilenameRegex = regexp.MustCompile(`^[a-zA-Z0-9_.-]+(?:\.[a-zA-Z0-9]+)?$`)

// Maximum allowed file size to prevent Denial of Service.
const maxFileSize = 1024 * 1024 // 1MB

/**
Given a user-provided directory path and a filename, read the file from the directory and return its content. If any error occurs during the file reading process (e.g. file not found, permission error), return an empty string. The returned string will be freed by the caller.

@param filename The name of the file to read, requested by a user.
@param dir_path The path of the directory where the file is located.

@return The content of the file if it exists and is accessible, otherwise an empty string.
*/
func readFileFromDir(filename, dirPath string) string {
	// 1. Validate and sanitize filename
	// Guideline #4: Validate user input to limit the character set.
	// Refined regex for filename validation.
	if !validFilenameRegex.MatchString(filename) {
		return ""
	}

	// Guideline #8: Do not allow more than a single "." character in a user-provided filepath.
	// This is now handled by the refined regex.

	// 2. Validate and sanitize directory path
	// Ensure dirPath is not empty.
	if dirPath == "" {
		return ""
	}

	// Ensure dirPath does not contain malicious sequences like "..".
	if strings.Contains(dirPath, "..") {
		return ""
	}

	// Construct the full path.
	fullPath := filepath.Join(dirPath, filename)

	// Canonicalize the base directory.
	absAllowedBaseDir, err := filepath.Abs(allowedBaseDir)
	if err != nil {
		return ""
	}

	// Use filepath.Rel to check if the full path is a subdirectory of the allowed base directory.
	// This is a more robust and idiomatic way to perform this check.
	relPath, err := filepath.Rel(absAllowedBaseDir, filepath.Join(absAllowedBaseDir, fullPath))
	if err != nil {
		return ""
	}

	// If relPath starts with "..", it means it's outside the allowed base directory.
	if strings.HasPrefix(relPath, "..") {
		return ""
	}

	// Construct the final, secured path.
	securedPath := filepath.Join(absAllowedBaseDir, relPath)

	// 3. Read the file with chunking and size limit to prevent DoS
	file, err := os.Open(securedPath)
	if err != nil {
		return ""
	}
	defer file.Close()

	// Use a buffered reader to read in chunks.
	reader := bufio.NewReader(file)
	var contentBuilder strings.Builder
	buffer := make([]byte, 4096) // Read in 4KB chunks

	for {
		n, err := reader.Read(buffer)
		if err != nil && err != io.EOF {
			return ""
		}
		if n == 0 {
			break
		}
		contentBuilder.Write(buffer[:n])

		// Implement a check to limit the total size of the content being read.
		if contentBuilder.Len() > maxFileSize {
			return ""
		}
	}

	// 4. File Type/Content Validation (Optional but recommended)
	// This example does not implement specific file type or content validation,
	// as it depends on the expected file types and how the content will be used.

	return contentBuilder.String()
