import (
	"archive/tar"
	"io"
	"os"
	"path/filepath"
	"strings"
)

/**
Extract the content of the tar file to the given destination path.
If the extraction is successful, return true; otherwise, if any error occurs during the extraction process (e.g. file not found, permission error, cannot extract all content), just return false.

@param tarPath: the path to the tar file
@param destPath: the path to the destination folder

@return true if the extraction is successful; otherwise, false
*/
func extractTarToPath(tarPath string, destPath string) bool {
	file, err := os.Open(tarPath)
	if err != nil {
		return false
	}
	defer file.Close()

	tr := tar.NewReader(file)

	// Ensure destPath is an absolute path and normalized.
	absDestPath, err := filepath.Abs(filepath.Clean(destPath))
	if err != nil {
		return false
	}
	// Ensure absDestPath has a trailing separator for consistent prefix checks.
	absDestPath = absDestPath + string(os.PathSeparator)

	// Define a reasonable maximum file size. For example, 1GB.
	const maxFileSize = 1 << 30 // 1GB

	for {
		header, err := tr.Next()
		if err == io.EOF {
			break // End of archive
		}
		if err != nil {
			return false
		}

		// Security: Prevent directory traversal by ensuring header.Name does not contain ".."
		// This is a belt-and-suspenders approach, as filepath.Clean and Abs should handle it.
		if strings.Contains(header.Name, "..") {
			return false
		}

		// Construct the full target path.
		targetPath := filepath.Join(destPath, header.Name)

		// Security: Validate the output path to prevent directory traversal.
		// Ensure the cleaned target path is an absolute path and starts with the absolute destination path.
		cleanedTargetPath, err := filepath.Abs(filepath.Clean(targetPath))
		if err != nil {
			return false
		}

		if !strings.HasPrefix(cleanedTargetPath, absDestPath) {
			return false
		}

		// Security: Sanitize permissions. Mask out potentially dangerous bits.
		mode := os.FileMode(header.Mode)
		// Mask out SUID, SGID, Sticky bits
		mode = mode &^ (os.ModeSetuid | os.ModeSetgid | os.ModeSticky)

		// Apply a more restrictive default permission mask for files and directories.
		// For files, default to 0644. For directories, default to 0755.
		// This is a security measure to prevent overly permissive files from being created.
		if header.Typeflag == tar.TypeDir {
			// If original mode has execute bits, preserve them for directories.
			// Otherwise, use 0755.
			if mode&0111 == 0 {
				mode = (mode &^ 0777) | 0755
			}
		} else {
			// For files, default to 0644.
			mode = (mode &^ 0777) | 0644
		}

		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(cleanedTargetPath, mode); err != nil {
				return false
			}
		case tar.TypeReg:
			// Ensure parent directory exists
			parentDir := filepath.Dir(cleanedTargetPath)
			if err := os.MkdirAll(parentDir, mode); err != nil {
				return false
			}

			// Security: Prevent excessively large files (Tar Bomb).
			if header.Size > maxFileSize {
				return false
			}

			outFile, err := os.OpenFile(cleanedTargetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, mode)
			if err != nil {
				return false
			}
			if _, err := io.Copy(outFile, tr); err != nil {
				outFile.Close()
				return false
			}
			outFile.Close()
		case tar.TypeSymlink:
			// Security: Prevent symlinks pointing outside the destination.
			linkTarget := header.Linkname

			// Resolve the symlink target relative to the directory containing the symlink.
			resolvedLinkTarget := linkTarget
			if !filepath.IsAbs(linkTarget) {
				// Resolve relative to the directory of the symlink within the archive.
				resolvedLinkTarget = filepath.Join(filepath.Dir(header.Name), linkTarget)
			}

			// Get the absolute path of where the symlink would point on the host.
			// This is done by joining the absolute destination path with the resolved link target.
			absResolvedLinkTarget, err := filepath.Abs(filepath.Join(absDestPath, resolvedLinkTarget))
			if err != nil {
				return false
			}

			// Ensure the resolved link target is still within the destination directory.
			if !strings.HasPrefix(absResolvedLinkTarget, absDestPath) {
				return false
			}

			// Create the symlink. The target for os.Symlink is the resolved path.
			if err := os.Symlink(resolvedLinkTarget, cleanedTargetPath); err != nil {
				return false
			}
		case tar.TypeLink:
			// Security: Handle hard links explicitly.
			// The header.Linkname for TypeLink is the target path.
			linkTarget := header.Linkname

			// Resolve the hardlink target relative to the archive root.
			resolvedLinkTarget := linkTarget
			if !filepath.IsAbs(linkTarget) {
				// Resolve relative to the directory of the hardlink within the archive.
				resolvedLinkTarget = filepath.Join(filepath.Dir(header.Name), linkTarget)
			}

			// Get the absolute path of where the hardlink would point on the host.
			absResolvedLinkTarget, err := filepath.Abs(filepath.Join(absDestPath, resolvedLinkTarget))
			if err != nil {
				return false
			}

			// Ensure the resolved link target is within the destination directory.
			if !strings.HasPrefix(absResolvedLinkTarget, absDestPath) {
				return false
			}

			// Create the hard link. The target for os.Link is the resolved path.
			if err := os.Link(resolvedLinkTarget, cleanedTargetPath); err != nil {
				return false
			}
		default:
			// Security: Explicitly reject unknown or potentially dangerous file types.
			// This includes device files, FIFOs, etc.
			return false
		}
	}

	return true
}

