// isValidAcceptLanguage checks if the provided string is a valid Accept-Language header value.
// This validation adheres more strictly to RFC 4647 by checking for valid language tags and quality values.
func isValidAcceptLanguage(lang string) bool {
	// RFC 4647 allows for language tags with subtags, and quality values between 0.0 and 1.0.
	// This regex is more comprehensive:
	// ^[a-zA-Z]{2,8}(-[a-zA-Z0-9]{1,8})*(\s*;\s*q=(0(\.\d{0,3})?|1(\.0{0,3})?))?$
	// - ^[a-zA-Z]{2,8}: Primary language subtag (2-8 letters).
	// - (-[a-zA-Z0-9]{1,8})*: Optional subtags (e.g., region, script, variant).
	// - (\s*;\s*q=(0(\.\d{0,3})?|1(\.0{0,3})?))?: Optional quality value (q=0.0 to q=1.0).
	//   - 0(\.\d{0,3})?: Matches 0 or 0.xxx (up to 3 decimal places).
	//   - 1(\.0{0,3})?: Matches 1 or 1.0 or 1.00 or 1.000.
	// - $: End of string.
	// It also explicitly disallows newline characters.
	// Note: This regex doesn't validate the actual language codes themselves (e.g., it would allow 'xx-YY').
	// A full RFC 4647 validation would require a lookup table or a more complex parser.
	// However, this is a significant improvement over the previous version.
	langRegex := regexp.MustCompile(`^[a-zA-Z]{2,8}(-[a-zA-Z0-9]{1,8})*(\s*;\s*q=(0(\.\d{0,3})?|1(\.0{0,3})?))?$`)
	return langRegex.MatchString(lang) && !strings.ContainsAny(lang, "\r\n")
}

// isValidAcceptEncoding checks if the provided string is a valid Accept-Encoding header value.
