	// q=(0(\.\d{0,3})?|1(\.0{0,3})?)
	qualityRegex := regexp.MustCompile(`^q=(0(\.\d{0,3})?|1(\.0{0,3})?)$`)

	// Split by comma and trim whitespace for each encoding.
	encodings := strings.Split(encoding, ",")
	for _, enc := range encodings {
		trimmedEnc := strings.TrimSpace(enc)
		if trimmedEnc == "" {
			return false // Empty encoding part is invalid
		}

		// Check for quality values (e.g., "gzip;q=1.0")
		parts := strings.Split(trimmedEnc, ";")
		encodingType := strings.ToLower(parts[0])

		if _, ok := validEncodings[encodingType]; !ok {
			return false
		}

		// Validate quality values if present
		if len(parts) > 1 {
			// There should be exactly one quality value part
			if len(parts) != 2 {
				return false
			}
			qualityPart := strings.TrimSpace(parts[1])
			if !qualityRegex.MatchString(qualityPart) {
				return false
			}
		} else {
			// If no quality value is specified, it defaults to q=1.0, which is valid.
			// No explicit check needed here as the absence of a quality part is handled.
		}
	}
	return !strings.ContainsAny(encoding, "\r\n")
}

