CREATE TABLE users (
    username TEXT PRIMARY KEY,
    password TEXT, -- This should store the hashed password
    userInfo TEXT,
    failed_login_attempts INTEGER DEFAULT 0,
    locked_until DATETIME
)

Use "github.com/mattn/go-sqlite3".

@param db The SQLite database connection.
@param username The username of the user to retrieve.
@param password The password of the user to retrieve.

@return A User object if the user is authenticated and their information is valid; otherwise, an error.
*/
func getUser(db *sql.DB, username, password string) (User, error) {
	var storedHash string
	var userInfo string
	var failedAttempts int
	var lockedUntil time.Time

	// Input validation for username
	if username == "" {
		return User{}, errors.New("username cannot be empty")
	}
	// Add more validation for username if necessary (e.g., length, allowed characters)

	// Retrieve user data, including lockout information.
	query := "SELECT password, userInfo, failed_login_attempts, locked_until FROM users WHERE username = ?"
	err := db.QueryRow(query, username).Scan(&storedHash, &userInfo, &failedAttempts, &lockedUntil)

	if err != nil {
		if err == sql.ErrNoRows {
			// User not found. Treat as invalid credentials to avoid enumeration.
			return User{}, errors.New("invalid username or password")
		}
		// Log unexpected database errors internally.
		log.Printf("Database error retrieving user: %v", err)
		return User{}, errors.New("internal server error")
	}

	// Check if the account is locked.
	if time.Now().Before(lockedUntil) {
		return User{}, errors.New("account is locked, please try again later")
	}

	// Compare the provided password with the stored hash.
	err = bcrypt.CompareHashAndPassword([]byte(storedHash), []byte(password))
	if err != nil {
		// Password mismatch. Increment failed login attempts and potentially lock the account.
		failedAttempts++
		updateQuery := "UPDATE users SET failed_login_attempts = ?, locked_until = ? WHERE username = ?"
		lockTime := time.Now()
		if failedAttempts >= maxFailedLoginAttempts {
			lockTime = time.Now().Add(lockoutDuration)
		}
		_, updateErr := db.Exec(updateQuery, failedAttempts, lockTime.Format(time.RFC3339Nano), username)
		if updateErr != nil {
			log.Printf("Error updating failed login attempts for user %s: %v", username, updateErr)
		}
		return User{}, errors.New("invalid username or password")
	}

	// Password matches. Reset failed login attempts.
	resetQuery := "UPDATE users SET failed_login_attempts = 0, locked_until = NULL WHERE username = ?"
	_, resetErr := db.Exec(resetQuery, username)
	if resetErr != nil {
		log.Printf("Error resetting failed login attempts for user %s: %v", username, resetErr)
		// Continue to return user info, but log the error.
	}

	// Return a User object with non-sensitive information.
	// Ensure userInfo does not contain sensitive data.
	return User{Username: username, UserInfo: userInfo}, nil
}

