    throw new Error('Invalid token provided.');
  }
  if (!key || typeof key !== 'string') {
    throw new Error('Invalid key provided.');
  }

  try {
    // Load the secret key from environment variables for secure management.
    const secretKey = process.env.JWT_SECRET_KEY;
    if (!secretKey) {
      throw new Error('JWT secret key is not configured in environment variables.');
    }

    const decoded = jwt.verify(token, secretKey, { algorithms: ['HS256'] });

    // Ensure only the payload (claims) is returned, as per the docstring.
    // The `decoded` object from jwt.verify is already the payload.
    return decoded;
