/**
Hash the given certificate securely and return the hash as a hexadecimal string.
The caller is responsible for freeing the returned string using free().

@param cert The certificate data to be hashed.
@param cert_len The length of the certificate data.

@return The securely hashed certificate as a hexadecimal string, or NULL on error.
*/
char* hash_certificate(const unsigned char *cert, size_t cert_len) {
    // Input validation: Ensure cert is not NULL and cert_len is positive.
    // The critique notes that validating cert_len against the actual size of cert
    // is often not possible within the function itself if cert is a char*.
    // However, by changing cert to unsigned char*, we semantically indicate
    // that it's binary data, and the caller is responsible for providing the correct length.
    if (cert == NULL || cert_len == 0) {
        return NULL;
    }

    EVP_MD_CTX *mdctx = NULL;
    const EVP_MD *md = NULL;
    unsigned char md_value[EVP_MAX_MD_SIZE];
    unsigned int md_len = 0;
    char *hex_hash = NULL;

    // Use SHA256 for a secure hash
    md = EVP_get_digestbyname("sha256");
    if (md == NULL) {
        // Error: could not get SHA256 digest.
        // The comment is updated for clarity as per critique.
        return NULL;
    }

    mdctx = EVP_MD_CTX_new();
    if (mdctx == NULL) {
        // Error: could not create MD_CTX
        return NULL;
    }

    if (1 != EVP_DigestInit_ex(mdctx, md, NULL)) {
        // Error: could not initialize digest
        EVP_MD_CTX_free(mdctx);
        return NULL;
    }

    // Use the provided length instead of strlen for robustness.
    // The critique highlighted the potential for buffer over-read if cert_len is
    // larger than the actual data. This is a caller responsibility.
    if (1 != EVP_DigestUpdate(mdctx, cert, cert_len)) {
        // Error: could not update digest
        EVP_MD_CTX_free(mdctx);
        return NULL;
    }

    if (1 != EVP_DigestFinal_ex(mdctx, md_value, &md_len)) {
        // Error: could not finalize digest
        EVP_MD_CTX_free(mdctx);
        return NULL;
    }

    EVP_MD_CTX_free(mdctx);
    mdctx = NULL; // Set to NULL after freeing

    // Theoretical check for EVP_MAX_MD_SIZE overflow, though highly unlikely.
    if (md_len > EVP_MAX_MD_SIZE) {
        // Error: digest size exceeds expected maximum.
        return NULL;
    }

    // Allocate memory for the hexadecimal string
    // Each byte of hash needs 2 hex characters + null terminator
    hex_hash = (char *)malloc(md_len * 2 + 1);
    if (hex_hash == NULL) {
        // Error: memory allocation failed
        return NULL;
    }

    // Convert the hash to a hexadecimal string using snprintf for safety
    for (unsigned int i = 0; i < md_len; i++) {
        // snprintf is safer than sprintf as it prevents buffer overflows.
        // We provide 3 bytes: 2 for the hex characters and 1 for the null terminator.
        snprintf(&hex_hash[i * 2], 3, "%02x", md_value[i]);
    }
    hex_hash[md_len * 2] = '\0'; // Null terminate the string

    return hex_hash;
}

