    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, actual_key, iv)) {
        // perror("Failed to initialize encryption"); // Removed for no print statements
        EVP_CIPHER_CTX_free(ctx);
        free(actual_key);
        free(iv);
        return result;
    }

    // Allocate buffer for ciphertext.
    // The ciphertext will be at most data_len + block_size - 1 bytes long.
    // Using EVP_CIPHER_block_size(cipher) is more robust than AES_BLOCK_SIZE.
    encrypted_data = (unsigned char*)malloc(data_len + EVP_CIPHER_block_size(cipher));
    if (!encrypted_data) {
        // perror("Failed to allocate memory for encrypted_data"); // Removed for no print statements
        EVP_CIPHER_CTX_free(ctx);
