    // EVP_EncryptFinal_ex will handle padding.
    if (1 != EVP_EncryptFinal_ex(ctx, encrypted_data + len, &len)) {
        // perror("Failed to finalize encryption"); // Removed for no print statements
        EVP_CIPHER_CTX_free(ctx);
        free(actual_key);
        free(iv);
        free(encrypted_data);
        return result;
