@param results The string content to write to the temporary file
@return A dynamically allocated string containing the temporary file name.
 */
char* write_results(const char* results) {
    // Use mkstemp for secure temporary file creation.
    // It generates a unique filename, creates the file, and returns a file descriptor.
    // The template string will be modified by mkstemp to contain the actual filename.
    // Ensure the template has enough 'X' characters for mkstemp to replace.
    char template[] = "/tmp/myapp_XXXXXX"; // Common temporary directory, adjust if needed.
    int fd = mkstemp(template);

    if (fd == -1) {
        // mkstemp failed. errno will contain the error code.
        return NULL;
    }

    // Open the file for writing using the file descriptor.
    // fdopen associates a stream with the file descriptor.
    FILE* temp_file = fdopen(fd, "w");
    if (temp_file == NULL) {
        // fdopen failed. Close the file descriptor and remove the created file.
        close(fd);
        unlink(template); // unlink removes the file
        return NULL;
    }

    // Explicitly set restrictive permissions (0600: owner read/write only)
    // This is done after fdopen to operate on the opened file stream.
    if (fchmod(fd, S_IRUSR | S_IWUSR) == -1) {
        // fchmod failed. Close the file (which also closes the fd) and remove the file.
        fclose(temp_file);
        unlink(template);
        return NULL;
    }

    // Write the results to the temporary file.
    if (fputs(results, temp_file) == EOF) {
        // fputs failed. Close the file (which also closes the fd) and remove the file.
        fclose(temp_file);
        unlink(template);
        return NULL;
    }

    // Close the file. fclose will also close the underlying file descriptor.
    // The file is now written and closed.
    if (fclose(temp_file) != 0) {
        // fclose failed. Remove the file.
        unlink(template);
        return NULL;
    }

    // Dynamically allocate memory for the filename and copy it.
    // strdup allocates memory and copies the string.
    char* allocated_filename = strdup(template);
    if (allocated_filename == NULL) {
        // strdup failed (memory allocation error). Remove the file.
        unlink(template);
        return NULL;
    }

    // Return the dynamically allocated filename.
    // The caller is responsible for freeing this memory using free()
    // and for deleting the temporary file using unlink().
    return allocated_filename;
}

