encryption_result encrypt_data(
    const std::vector<unsigned char>& key,
    const std::vector<unsigned char>& data
) {
    // Use AES-256 for encryption. The key size for AES-256 is 32 bytes.
    if (key.size() < 32) {
        throw std::invalid_argument("Key must be at least 32 bytes long for AES-256.");
    }
    std::vector<unsigned char> aes_key(key.begin(), key.begin() + 32);

    // Initialize AES-256-GCM context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        throw std::runtime_error("Failed to create cipher context.");
    }

    // Generate a random IV (12 bytes is standard for GCM)
    std::vector<unsigned char> iv(EVP_GCM_TLS_IV_LEN);
    if (RAND_bytes(iv.data(), iv.size()) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Failed to generate random IV.");
